519	// ---------- commission_split_reverse ----------
520	
521	/**
522	 * Reverses a prior split (refund, dispute lost).
523	 * Inserts a new row with kind='reversal' and parent_split_id = original.
524	 * Returns the reversal row id.
525	 */
526	export interface CommissionSplitReverseArgs {
527	  parentSplitId: string;
528	  reverseAmountCents: CentsAmount;          // can be partial
529	  reverseTipCents: CentsAmount;
530	  reverseStripeTransferId: string | null;
531	}
532	export type CommissionSplitReverseResult = { id: string };
533	
534	// ---------- stripe_dispute_record ----------
535	
536	export interface StripeDisputeRecordArgs {
537	  studioId: string;
538	  disputeId: string;
539	  chargeId: string;
540	  reason: string;
541	  status: StripeDisputeStatus;
542	  amountCents: CentsAmount;
543	  currency: Currency;
544	  evidenceDueBy: string;
