612	// ---------- apply_deposit_to_session (S16) ----------
613	
614	/**
615	 * SAGA STEP 1: Atomically reserve a deposit pool drawdown for an upcoming PaymentIntent.
616	 *
617	 * Behavior:
618	 *   1. SELECT FOR UPDATE on `projects.deposit_pool_cents_available`.
619	 *   2. Verify available >= draw_cents. RAISE EXCEPTION if not.
620	 *   3. Decrement available, increment applied.
621	 *   4. INSERT into `project_deposit_transactions` with status='pending_apply'.
622	 *   5. Return the transaction id.
623	 *
624	 * Caller flow: call this BEFORE stripe.paymentIntents.create(). Pass the returned
625	 * transaction_id in the PaymentIntent metadata. The webhook handler then calls:
626	 *   - confirm_deposit_application(txn_id) on payment_intent.succeeded
627	 *   - rollback_deposit_application(txn_id) on payment_intent.payment_failed | canceled
628	 *
629	 * If the caller fails to create the PaymentIntent, they MUST call rollback explicitly.
630	 * A reaper cron should sweep `pending_apply` rows older than 30 minutes and roll them back.
631	 */
632	export interface ApplyDepositToSessionArgs {
633	  projectId: string;
634	  sessionId: string;
635	  drawCents: CentsAmount;
636	  idempotencyKey: InkosIdempotencyKey;          // dedupe on PaymentIntent retries
637	}
638	export type ApplyDepositToSessionResult = {
639	  transaction_id: string;
640	  pool_in_cents: CentsAmount;
641	  pool_applied_cents: CentsAmount;
642	  pool_available_cents: CentsAmount;
643	};
