645	// ---------- confirm_deposit_application (S16) ----------
646	
647	/**
648	 * SAGA STEP 2 (success path): Mark a pending_apply transaction as applied.
649	 * Called from the webhook handler on payment_intent.succeeded.
650	 *
651	 * Idempotent — re-running on an already-confirmed txn is a no-op.
652	 * RAISE EXCEPTION if txn was already rolled_back or released.
653	 */
654	export interface ConfirmDepositApplicationArgs {
655	  transactionId: string;
656	  paymentIntentId: string;                      // for cross-reference
657	}
658	export type ConfirmDepositApplicationResult = {
659	  transaction_id: string;
660	  status: 'applied' | 'already_applied';
661	};
662	
663	// ---------- rollback_deposit_application (S16) ----------
664	
665	/**
666	 * SAGA STEP 2 (failure path): Roll back a pending_apply transaction.
667	 * Called from the webhook handler on payment_intent.payment_failed | canceled,
668	 * OR by the reaper cron after 30-min timeout.
669	 *
670	 * Behavior:
671	 *   1. SELECT FOR UPDATE on the txn + parent project.
672	 *   2. Re-increment available, decrement applied.
673	 *   3. Mark txn status='rolled_back', set rolled_back_at + reason.
674	 *
675	 * Idempotent — re-running on an already-rolled-back txn is a no-op.
676	 * RAISE EXCEPTION if txn is already 'applied' (cannot rollback a confirmed txn —
677	 * issue a refund instead via release_deposit_from_session).
678	 */
679	export interface RollbackDepositApplicationArgs {
680	  transactionId: string;
681	  reason: 'payment_failed' | 'payment_canceled' | 'reaper_timeout' | 'manual';
682	}
683	export type RollbackDepositApplicationResult = {
684	  transaction_id: string;
685	  status: 'rolled_back' | 'already_rolled_back';
686	  pool_available_cents: CentsAmount;
687	};
688	
689	// ---------- release_deposit_from_session (S16) ----------
690	
691	/**
692	 * Refund path: re-credit a previously-applied deposit drawdown back to the pool.
693	 *
694	 * Called from refund flow when the original session charge consumed pool funds.
695	 * Partial refunds are supported (release_cents <= original draw_cents).
696	 *
697	 * Behavior:
698	 *   1. SELECT FOR UPDATE on the txn + parent project.
699	 *   2. Verify txn status='applied' (cannot release pending/rolled_back).
700	 *   3. Verify release_cents <= (txn.draw_cents - already-released amount).
701	 *   4. Re-increment available, decrement applied (by release_cents).
702	 *   5. INSERT a child txn with kind='released', parent_transaction_id=txn_id.
703	 *
704	 * NOT idempotent on its own — caller passes a unique idempotency_key in args
705	 * to dedupe on Stripe webhook replay (charge.refunded fires multiple times).
706	 */
707	export interface ReleaseDepositFromSessionArgs {
708	  transactionId: string;                        // original applied txn
709	  releaseCents: CentsAmount;
710	  idempotencyKey: InkosIdempotencyKey;
711	  refundId: string;                             // Stripe refund_xxx for cross-reference
712	}
713	export type ReleaseDepositFromSessionResult = {
714	  release_transaction_id: string;
715	  pool_available_cents: CentsAmount;
716	  total_released_cents: CentsAmount;            // running total released against parent txn
717	};
718	
719	// ---------- studio_l2_payments_enabled (S15) ----------
720	
721	/**
722	 * Capability gate: returns true only if the studio has an active Stripe Connect
723	 * account with `charges_enabled` capability. Used by S16+ in-studio charge code
724	 * paths to refuse charges before the studio's KYC is complete.
725	 *
726	 * Called from: feature-gate layer + UI banner suppression on /dashboard.
727	 *
728	 * `reason` is populated only when `enabled=false`. Possible values:
729	 *   - 'no_connected_account'      — studio has not started Connect onboarding
730	 *   - 'onboarding_pending'        — account exists but KYC incomplete
731	 *   - 'onboarding_restricted'     — Stripe restricted the account (KYC docs needed)
732	 *   - 'onboarding_rejected'       — Stripe permanently rejected
733	 *   - 'charges_disabled'          — Stripe revoked charges capability
734	 */
735	export interface StudioL2PaymentsEnabledArgs {
736	  studioId: string;
737	}
738	export type StudioL2PaymentsEnabledResult = {
739	  enabled: boolean;
740	  reason: string | null;
741	  account_id: string | null;
742	  onboarding_status: ConnectedAccountOnboardingStatus | null;
743	};
744	
745	// ---------- artist_l2_payouts_enabled (S15) ----------
746	
747	/**
748	 * Capability gate for artists who opt into direct payouts.
749	 * Returns true only if the artist has their own active Stripe Connect account
750	 * with `payouts_enabled` AND `transfers` capabilities.
751	 *
752	 * If false, commission splits flow to the studio's connected account and the
753	 * studio pays the artist via existing payroll path (1099 or W-2).
754	 *
755	 * `reason` possible values:
756	 *   - 'self_payouts_disabled'     — artist hasn't opted in (`payouts_self_enabled=false`)
757	 *   - 'no_connected_account'      — opted in but no Stripe account created yet
758	 *   - 'onboarding_pending'        — account exists, KYC incomplete
759	 *   - 'onboarding_restricted'     — Stripe restricted
760	 *   - 'onboarding_rejected'       — permanently rejected
761	 *   - 'transfers_disabled'        — capability missing
762	 *   - 'payouts_disabled'          — capability missing
763	 */
764	export interface ArtistL2PayoutsEnabledArgs {
765	  artistId: string;
766	}
767	export type ArtistL2PayoutsEnabledResult = {
768	  enabled: boolean;
769	  reason: string | null;
770	  account_id: string | null;
