/**
 * RPC contract tests: commission_split_tax_line_reverse (S18)
 *
 * DB-gated. Per-test studio + parent split + tax_line child fixture.
 *
 * Coverage (6 tests):
 *  1. Happy path — inserts reversal row with negative tax_amount_cents linked to parent tax_line
 *  2. Idempotency — same (parent_tax_line_split_id, refund_id) returns same id, created: false
 *  3. Bounds — cumulative reversal exceeds parent tax_amount_cents → RAISE EXCEPTION
 *  4. Parent not kind='tax_line' → RAISE EXCEPTION ("parent kind must be tax_line")
 *  5. Parent not found → RAISE EXCEPTION
 *  6. release_tax_cents <= 0 → RAISE EXCEPTION
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestArtist,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type CommissionSplitTaxLineReverseArgs,
  type CommissionSplitTaxLineReverseResult,
  type CommissionSplitTaxLineRecordResult,
  type CommissionSplitRecordResult,
  type InkosIdempotencyKey,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: commission_split_tax_line_reverse', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let artistId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const artist = await createTestArtist(studioId)
    artistId = artist.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  /** Insert a parent commission_splits row of kind='split'. Returns the row id. */
  async function createParentSplit(): Promise<string> {
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_RECORD, {
      p_studio_id: studioId,
      p_booking_id: null,
      p_session_id: null,
      p_artist_id: artistId,
      p_base_amount_cents: cents(10000),
      p_commission_pct: 70,
      p_tip_amount_cents: cents(0),
      p_applied_from_pool_cents: cents(0),
      p_stripe_transfer_id: null,
      p_kind: 'split',
    })
    if (error) throw new Error(`createParentSplit failed: ${error.message}`)
    return (data as CommissionSplitRecordResult).id
  }

  /** Insert a kind='tax_line' child under a parent split. Returns its id. */
  async function createTaxLineChild(
    parentSplitId: string,
    taxAmountCents: number,
    jurisdiction = 'US-NY-NYC',
  ): Promise<string> {
    const taxLineId = `taxline_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_TAX_LINE_RECORD, {
      p_parent_split_id: parentSplitId,
      p_tax_line_id: taxLineId,
      p_jurisdiction: jurisdiction,
      p_tax_amount_cents: cents(taxAmountCents),
    })
    if (error) throw new Error(`createTaxLineChild failed: ${error.message}`)
    return (data as CommissionSplitTaxLineRecordResult).id
  }

  function makeIdemKey(suffix?: string): InkosIdempotencyKey {
    return `inkos_rev_${(suffix ?? randomUUID()).replace(/-/g, '').slice(0, 24)}` as InkosIdempotencyKey
  }

  function makeRefundId(): string {
    return `re_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
  }

  async function callReverseRpc(
    args: CommissionSplitTaxLineReverseArgs,
  ): Promise<{ data: CommissionSplitTaxLineReverseResult | null; error: { message: string } | null }> {
    const { data, error } = await sb.rpc(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE, {
      p_parent_tax_line_split_id: args.parentTaxLineSplitId,
      p_release_tax_cents: args.releaseTaxCents,
      p_refund_id: args.refundId,
      p_idempotency_key: args.idempotencyKey,
    })
    return {
      data: data as CommissionSplitTaxLineReverseResult | null,
      error,
    }
  }

  // ---------------------------------------------------------------------------
  // Tests
  // ---------------------------------------------------------------------------

  it('happy path — inserts reversal row with negative tax_amount_cents linked to parent tax_line', async () => {
    const parentSplitId = await createParentSplit()
    const taxLineId = await createTaxLineChild(parentSplitId, 500)
    const refundId = makeRefundId()
    const idemKey = makeIdemKey()

    const { data, error } = await callReverseRpc({
      parentTaxLineSplitId: taxLineId,
      releaseTaxCents: cents(500),
      refundId,
      idempotencyKey: idemKey,
    })

    expect(error).toBeNull()
    expect(data).not.toBeNull()

    const result = data as CommissionSplitTaxLineReverseResult
    expect(typeof result.reversal_id).toBe('string')
    expect(result.reversal_id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )
    expect(result.created).toBe(true)
    expect(result.total_reversed_cents).toBe(500)

    // Verify the inserted row has negative tax_amount_cents + correct linkage
    const { data: row } = await sb
      .from('commission_splits')
      .select('id, kind, parent_split_id, tax_amount_cents')
      .eq('id', result.reversal_id)
      .maybeSingle()

    expect(row).not.toBeNull()
    expect(row?.kind).toBe('reversal')
    expect(row?.parent_split_id).toBe(taxLineId)
    // Stored as negative to indicate reversal direction
    expect(row?.tax_amount_cents).toBe(-500)
  })

  it('idempotency — same (parent_tax_line_split_id, refund_id) returns same id, created: false', async () => {
    const parentSplitId = await createParentSplit()
    const taxLineId = await createTaxLineChild(parentSplitId, 300)
    const refundId = makeRefundId()
    const idemKey = makeIdemKey()

    const args: CommissionSplitTaxLineReverseArgs = {
      parentTaxLineSplitId: taxLineId,
      releaseTaxCents: cents(300),
      refundId,
      idempotencyKey: idemKey,
    }

    const { data: first, error: e1 } = await callReverseRpc(args)
    const { data: second, error: e2 } = await callReverseRpc(args)

    expect(e1).toBeNull()
    expect(e2).toBeNull()

    const r1 = first as CommissionSplitTaxLineReverseResult
    const r2 = second as CommissionSplitTaxLineReverseResult

    expect(r1.reversal_id).toBe(r2.reversal_id)
    expect(r1.created).toBe(true)
    expect(r2.created).toBe(false)
    // total_reversed_cents must not double-count on replay
    expect(r2.total_reversed_cents).toBe(300)

    // Only 1 reversal row in DB
    const { count } = await sb
      .from('commission_splits')
      .select('id', { count: 'exact', head: true })
      .eq('parent_split_id', taxLineId)
      .eq('kind', 'reversal')

    expect(count).toBe(1)
  })

  it('bounds — cumulative reversal exceeds parent tax_amount_cents → RAISE EXCEPTION', async () => {
    const parentSplitId = await createParentSplit()
    const taxLineId = await createTaxLineChild(parentSplitId, 200)

    // First reversal — within bounds
    const { error: e1 } = await callReverseRpc({
      parentTaxLineSplitId: taxLineId,
      releaseTaxCents: cents(200),
      refundId: makeRefundId(),
      idempotencyKey: makeIdemKey(),
    })
    expect(e1).toBeNull()

    // Second reversal — pushes cumulative above 200 → must fail
    const { data, error: e2 } = await callReverseRpc({
      parentTaxLineSplitId: taxLineId,
      releaseTaxCents: cents(100),
      refundId: makeRefundId(),
      idempotencyKey: makeIdemKey(),
    })

    expect(data).toBeNull()
    expect(e2).not.toBeNull()
    expect(
      e2?.message?.toLowerCase().includes('exceed') ||
      e2?.message?.toLowerCase().includes('cumulative') ||
      e2?.message?.toLowerCase().includes('over') ||
      e2?.message?.toLowerCase().includes('cannot reverse'),
    ).toBe(true)
  })

  it('parent not kind=tax_line → RAISE EXCEPTION ("parent kind must be tax_line")', async () => {
    // Create a plain 'split' row and attempt to reverse it as if it were a tax_line
    const parentSplitId = await createParentSplit()

    const { data, error } = await callReverseRpc({
      parentTaxLineSplitId: parentSplitId, // wrong — this is kind='split', not 'tax_line'
      releaseTaxCents: cents(100),
      refundId: makeRefundId(),
      idempotencyKey: makeIdemKey(),
    })

    expect(data).toBeNull()
    expect(error).not.toBeNull()
    expect(
      error?.message?.toLowerCase().includes('tax_line') ||
      error?.message?.toLowerCase().includes('kind must') ||
      error?.message?.toLowerCase().includes('parent kind') ||
      error?.message?.toLowerCase().includes('invalid parent'),
    ).toBe(true)
  })

  it('parent not found → RAISE EXCEPTION', async () => {
    const ghostId = randomUUID()

    const { data, error } = await callReverseRpc({
      parentTaxLineSplitId: ghostId,
      releaseTaxCents: cents(100),
      refundId: makeRefundId(),
      idempotencyKey: makeIdemKey(),
    })

    expect(data).toBeNull()
    expect(error).not.toBeNull()
    expect(
      error?.message?.toLowerCase().includes('not found') ||
      error?.message?.toLowerCase().includes('does not exist') ||
      error?.message?.toLowerCase().includes('parent'),
    ).toBe(true)
  })

  it('release_tax_cents <= 0 → RAISE EXCEPTION', async () => {
    const parentSplitId = await createParentSplit()
    const taxLineId = await createTaxLineChild(parentSplitId, 400)

    const { data, error } = await callReverseRpc({
      parentTaxLineSplitId: taxLineId,
      releaseTaxCents: cents(0),
      refundId: makeRefundId(),
      idempotencyKey: makeIdemKey(),
    })

    expect(data).toBeNull()
    expect(error).not.toBeNull()
    expect(
      error?.message?.toLowerCase().includes('must be') ||
      error?.message?.toLowerCase().includes('positive') ||
      error?.message?.toLowerCase().includes('greater than') ||
      error?.message?.toLowerCase().includes('release'),
    ).toBe(true)
  })
})

/**
 * RPC contract tests: tax_remittance_release (S18)
 *
 * DB-gated. Per-test studio + location + accrued ledger row fixture.
 *
 * Coverage (6 tests):
 *  1. Happy path — decrements ledger, inserts tracking row, returns new_collected_cents
 *  2. Idempotency — same idempotency_key returns same release amount, no double-decrement
 *  3. Release > collected → RAISE EXCEPTION
 *  4. release_amount_cents <= 0 → RAISE EXCEPTION
 *  5. Ledger row not found → RAISE EXCEPTION
 *  6. Multi-release — two releases against same ledger row → cumulative decrement, both tracked
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestLocation,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type TaxRemittanceReleaseArgs,
  type TaxRemittanceReleaseResult,
  type TaxRemittanceAccrueResult,
  type InkosIdempotencyKey,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: tax_remittance_release', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let locationId: string

  beforeEach(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const location = await createTestLocation(studioId)
    locationId = location.id
  })

  afterEach(async () => {
    await cleanupStudio(studioId)
  })

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  const TEST_JURISDICTION = 'US-NY-NYC'
  const TEST_PERIOD = '2026-Q2'

  /** Accrue an amount into the ledger. Returns the ledger row id. */
  async function accrue(amountCents: number, jurisdiction = TEST_JURISDICTION, period = TEST_PERIOD): Promise<string> {
    const { data, error } = await sb.rpc(RPC.TAX_REMITTANCE_ACCRUE, {
      p_studio_id: studioId,
      p_location_id: locationId,
      p_jurisdiction: jurisdiction,
      p_period: period,
      p_amount_collected_cents: cents(amountCents),
    })
    if (error) throw new Error(`accrue failed: ${error.message}`)
    return (data as TaxRemittanceAccrueResult).id
  }

  function makeIdemKey(suffix?: string): InkosIdempotencyKey {
    return `inkos_rel_${(suffix ?? randomUUID()).replace(/-/g, '').slice(0, 24)}` as InkosIdempotencyKey
  }

  function makeRefundId(): string {
    return `re_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
  }

  async function callReleaseRpc(
    args: TaxRemittanceReleaseArgs,
  ): Promise<{ data: TaxRemittanceReleaseResult | null; error: { message: string } | null }> {
    const { data, error } = await sb.rpc(RPC.TAX_REMITTANCE_RELEASE, {
      p_studio_id: args.studioId,
      p_location_id: args.locationId,
      p_jurisdiction: args.jurisdiction,
      p_period: args.period,
      p_release_amount_cents: args.releaseAmountCents,
      p_idempotency_key: args.idempotencyKey,
      p_refund_id: args.refundId,
    })
    return {
      data: data as TaxRemittanceReleaseResult | null,
      error,
    }
  }

  function baseArgs(
    overrides: Partial<TaxRemittanceReleaseArgs> = {},
  ): TaxRemittanceReleaseArgs {
    return {
      studioId,
      locationId,
      jurisdiction: TEST_JURISDICTION,
      period: TEST_PERIOD,
      releaseAmountCents: cents(500),
      idempotencyKey: makeIdemKey(),
      refundId: makeRefundId(),
      ...overrides,
    }
  }

  // ---------------------------------------------------------------------------
  // Tests
  // ---------------------------------------------------------------------------

  it('happy path — decrements ledger, inserts tracking row, returns new_collected_cents', async () => {
    await accrue(1000)

    const { data, error } = await callReleaseRpc(baseArgs({ releaseAmountCents: cents(500) }))

    expect(error).toBeNull()
    expect(data).not.toBeNull()

    const result = data as TaxRemittanceReleaseResult
    expect(typeof result.ledger_id).toBe('string')
    expect(result.ledger_id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )
    expect(result.released_cents).toBe(500)
    // 1000 - 500 = 500
    expect(result.new_collected_cents).toBe(500)

    // Verify the DB row was actually decremented
    const { data: ledgerRow } = await sb
      .from('tax_remittance_ledger')
      .select('amount_collected_cents')
      .eq('id', result.ledger_id)
      .maybeSingle()

    expect(ledgerRow?.amount_collected_cents).toBe(500)
  })

  it('idempotency — same idempotency_key returns same release amount, no double-decrement', async () => {
    await accrue(2000)

    const idemKey = makeIdemKey()
    const refundId = makeRefundId()
    const args = baseArgs({
      releaseAmountCents: cents(800),
      idempotencyKey: idemKey,
      refundId,
    })

    const { data: first, error: e1 } = await callReleaseRpc(args)
    const { data: second, error: e2 } = await callReleaseRpc(args)

    expect(e1).toBeNull()
    expect(e2).toBeNull()

    const r1 = first as TaxRemittanceReleaseResult
    const r2 = second as TaxRemittanceReleaseResult

    // Both return the same ledger_id
    expect(r1.ledger_id).toBe(r2.ledger_id)
    // released_cents matches on replay
    expect(r2.released_cents).toBe(800)
    // No double-decrement: 2000 - 800 = 1200 (not 400)
    expect(r2.new_collected_cents).toBe(1200)

    // Verify the DB row still shows 1200, not 400
    const { data: ledgerRow } = await sb
      .from('tax_remittance_ledger')
      .select('amount_collected_cents')
      .eq('id', r1.ledger_id)
      .maybeSingle()

    expect(ledgerRow?.amount_collected_cents).toBe(1200)
  })

  it('release > collected → RAISE EXCEPTION', async () => {
    await accrue(300)

    const { data, error } = await callReleaseRpc(
      baseArgs({ releaseAmountCents: cents(301) }),
    )

    expect(data).toBeNull()
    expect(error).not.toBeNull()
    expect(
      error?.message?.toLowerCase().includes('exceed') ||
      error?.message?.toLowerCase().includes('insufficient') ||
      error?.message?.toLowerCase().includes('negative') ||
      error?.message?.toLowerCase().includes('cannot release') ||
      error?.message?.toLowerCase().includes('greater than'),
    ).toBe(true)
  })

  it('release_amount_cents <= 0 → RAISE EXCEPTION', async () => {
    await accrue(1000)

    const { data, error } = await callReleaseRpc(
      baseArgs({ releaseAmountCents: cents(0) }),
    )

    expect(data).toBeNull()
    expect(error).not.toBeNull()
    expect(
      error?.message?.toLowerCase().includes('must be') ||
      error?.message?.toLowerCase().includes('positive') ||
      error?.message?.toLowerCase().includes('greater than') ||
      error?.message?.toLowerCase().includes('release'),
    ).toBe(true)
  })

  it('ledger row not found → RAISE EXCEPTION', async () => {
    // No accrue — no ledger row exists for this jurisdiction/period
    const { data, error } = await callReleaseRpc(
      baseArgs({
        jurisdiction: 'AU-VIC-MEL',
        period: '2099-Q1', // deliberately unaccrued period
        releaseAmountCents: cents(100),
      }),
    )

    expect(data).toBeNull()
    expect(error).not.toBeNull()
    expect(
      error?.message?.toLowerCase().includes('not found') ||
      error?.message?.toLowerCase().includes('does not exist') ||
      error?.message?.toLowerCase().includes('ledger') ||
      error?.message?.toLowerCase().includes('no row'),
    ).toBe(true)
  })

  it('multi-release — two releases against same ledger row → cumulative decrement, both tracked', async () => {
    await accrue(3000)

    const args1 = baseArgs({ releaseAmountCents: cents(1000) })
    const args2 = baseArgs({ releaseAmountCents: cents(500) })

    const { data: r1, error: e1 } = await callReleaseRpc(args1)
    const { data: r2, error: e2 } = await callReleaseRpc(args2)

    expect(e1).toBeNull()
    expect(e2).toBeNull()

    const result1 = r1 as TaxRemittanceReleaseResult
    const result2 = r2 as TaxRemittanceReleaseResult

    // Same ledger row targeted
    expect(result1.ledger_id).toBe(result2.ledger_id)

    // First release: 3000 - 1000 = 2000
    expect(result1.new_collected_cents).toBe(2000)
    // Second release: 2000 - 500 = 1500
    expect(result2.new_collected_cents).toBe(1500)

    // Verify final DB state
    const { data: ledgerRow } = await sb
      .from('tax_remittance_ledger')
      .select('amount_collected_cents')
      .eq('id', result1.ledger_id)
      .maybeSingle()

    expect(ledgerRow?.amount_collected_cents).toBe(1500)
  })
})

/**
 * RPC contract tests: commission_splits_drift_check — Leg 4 (S18)
 *
 * DB-gated. Tests the refunds_missing_tax_reversal output from the drift-check RPC.
 *
 * Leg 4 semantics: a refunded charge whose parent split has kind='reversal' rows
 * under it (the base reversal happened) but none of the tax_line children have
 * a corresponding kind='reversal' child of their own → missing_jurisdictions populated.
 *
 * Coverage (5 tests):
 *  1. Refunded charge WITH tax_line reversals → NOT in refunds_missing_tax_reversal
 *  2. Refunded charge WITHOUT tax_line reversals (base reversal exists, no tax_line reversal rows) → appears in list
 *  3. Status='succeeded' (not refunded) → NOT in list
 *  4. Charge with no tax_line children → NOT in list
 *  5. Old refunded charges (before since_timestamp) → NOT in list
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
