  ): Promise<void> {
    const idemKey =
      `inkos_rev_${randomUUID().replace(/-/g, '').slice(0, 24)}` as InkosIdempotencyKey
    const refundId = `re_test_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const { error } = await sb.rpc(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE, {
