  it('refunded charge WITH tax_line reversals → NOT in refunds_missing_tax_reversal', async () => {
    const piId = `pi_s18_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const chargeId = `ch_s18_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const since = new Date(Date.now() - 1000).toISOString()

    await insertStripeCharge({ paymentIntentId: piId, chargeId, status: 'refunded', taxAmountCents: 500 })
    const parentSplitId = await insertParentSplit()
    const taxLineChildId = await insertTaxLineChild(parentSplitId, 'US-NY-NYC', 500)
    await insertBaseReversal(parentSplitId)
    await insertTaxLineReversal(taxLineChildId, 500)

    const result = await runDriftCheck(since)

    const missingRefundIds = result.refunds_missing_tax_reversal.map((r) => r.refund_id ?? r.payment_intent_id)
    // This PI must NOT appear in the missing list
    const match = result.refunds_missing_tax_reversal.find((r) => r.payment_intent_id === piId)
    expect(match).toBeUndefined()
    // Suppress unused var lint
    void missingRefundIds
  })

  it('refunded charge WITHOUT tax_line reversals → appears in list with missing_jurisdictions', async () => {
    const piId = `pi_s18miss_${randomUUID().replace(/-/g, '').slice(0, 14)}`
    const chargeId = `ch_s18miss_${randomUUID().replace(/-/g, '').slice(0, 14)}`
    const since = new Date(Date.now() - 1000).toISOString()

    await insertStripeCharge({ paymentIntentId: piId, chargeId, status: 'refunded', taxAmountCents: 400 })
    const parentSplitId = await insertParentSplit()
    await insertTaxLineChild(parentSplitId, 'US-NY', 250)
    await insertTaxLineChild(parentSplitId, 'US-NY-NYC', 150)
    // Base reversal exists (the non-tax split was reversed)
    await insertBaseReversal(parentSplitId)
    // Tax-line reversals are MISSING — this is the drift condition

    const result = await runDriftCheck(since)

    const match = result.refunds_missing_tax_reversal.find((r) => r.payment_intent_id === piId)
    expect(match).toBeDefined()
    expect(match?.studio_id).toBe(studioId)
    // missing_jurisdictions should list the un-reversed jurisdictions
    expect(Array.isArray(match?.missing_jurisdictions)).toBe(true)
    expect(match?.missing_jurisdictions.length).toBeGreaterThan(0)
    expect(match?.missing_jurisdictions).toContain('US-NY')
  })

  it('status=succeeded (not refunded) → NOT in refunds_missing_tax_reversal list', async () => {
    const piId = `pi_s18succ_${randomUUID().replace(/-/g, '').slice(0, 14)}`
    const chargeId = `ch_s18succ_${randomUUID().replace(/-/g, '').slice(0, 14)}`
    const since = new Date(Date.now() - 1000).toISOString()

    // Succeeded charge with tax_lines but NO reversal of any kind — should not appear
    await insertStripeCharge({ paymentIntentId: piId, chargeId, status: 'succeeded', taxAmountCents: 500 })
    const parentSplitId = await insertParentSplit()
    await insertTaxLineChild(parentSplitId, 'US-CA', 500)
    // No reversals at all

    const result = await runDriftCheck(since)

    const match = result.refunds_missing_tax_reversal.find((r) => r.payment_intent_id === piId)
    expect(match).toBeUndefined()
  })

  it('charge with no tax_line children → NOT in refunds_missing_tax_reversal list', async () => {
    const piId = `pi_s18notax_${randomUUID().replace(/-/g, '').slice(0, 13)}`
    const chargeId = `ch_s18notax_${randomUUID().replace(/-/g, '').slice(0, 13)}`
    const since = new Date(Date.now() - 1000).toISOString()

    await insertStripeCharge({ paymentIntentId: piId, chargeId, status: 'refunded', taxAmountCents: 0 })
    const parentSplitId = await insertParentSplit()
    // No tax_line children inserted
    await insertBaseReversal(parentSplitId)

    const result = await runDriftCheck(since)

    const match = result.refunds_missing_tax_reversal.find((r) => r.payment_intent_id === piId)
    expect(match).toBeUndefined()
  })

  it('old refunded charges (before since_timestamp) → NOT in list', async () => {
    const piId = `pi_s18old_${randomUUID().replace(/-/g, '').slice(0, 15)}`
    const chargeId = `ch_s18old_${randomUUID().replace(/-/g, '').slice(0, 15)}`
    const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString()

    // Insert an old refunded charge with tax lines but no tax reversal — would appear if filter breaks
    await insertStripeCharge({
      paymentIntentId: piId,
      chargeId,
      status: 'refunded',
      taxAmountCents: 300,
      createdAt: twoHoursAgo,
    })
    const parentSplitId = await insertParentSplit()
    await insertTaxLineChild(parentSplitId, 'US-TX', 300)
    await insertBaseReversal(parentSplitId)
    // Intentionally skip tax_line reversal — would trigger Leg 4 if timestamp filter fails

    // Query with since = 1 hour ago — the 2-hour-old charge is outside the window
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString()
    const result = await runDriftCheck(oneHourAgo)

    const match = result.refunds_missing_tax_reversal.find((r) => r.payment_intent_id === piId)
    expect(match).toBeUndefined()
  })
})

/**
 * Integration tests: lib/stripe/refunds — S18 tax reversal extension
 *
 * Stripe SDK mocked. Supabase client mocked.
 * All tests run unconditionally (no DB required).
 *
 * Coverage (7 tests):
 *  1. Happy full refund WITH tax_lines → calls COMMISSION_SPLIT_TAX_LINE_REVERSE per child + TAX_REMITTANCE_RELEASE per jurisdiction
 *  2. Partial refund (50%) → release_tax_cents = Math.round(0.5 × parent.tax_amount_cents) per child
 *  3. No tax_line children → skips both new RPCs entirely
 *  4. INVARIANT 5 still holds: reverse_transfer: true + refund_application_fee: true
 *  5. Multiple jurisdictions (US-NY + US-NY-NYC) → 2 TAX_LINE_REVERSE calls + 2 TAX_REMITTANCE_RELEASE calls
 *  6. Idempotency — same refund_id retried → idempotency keys are deterministic for both RPCs
 *  7. Tax_line RPC failure → log error + continue (recoverable via Leg 4 reconciliation)
 */

