// ---------------------------------------------------------------------------
// Supabase mock factory
// ---------------------------------------------------------------------------

interface MockOptions {
  chargeRow?: Record<string, unknown> | null
  taxLineChildren?: TaxLineFixture[]
  parentSplitRow?: { id: string; stripe_transfer_id: string | null } | null
  taxLineReverseError?: { message: string } | null
  taxRemittanceReleaseError?: { message: string } | null
  commissionSplitError?: { message: string } | null
  statusUpdateError?: { message: string } | null
}

let capturedRpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

function makeSupabaseMock(opts: MockOptions = {}): SupabaseClient {
  const {
    chargeRow = makeChargeRow(),
    taxLineChildren = [
      {
        id: 'taxline-child-001',
        kind: 'tax_line',
        parent_split_id: 'split-s18-001',
        tax_amount_cents: 1800,
        jurisdiction: 'US-NY-NYC',
      },
    ],
    parentSplitRow = { id: 'split-s18-001', stripe_transfer_id: 'tr_test_s18_001' },
    taxLineReverseError = null,
    taxRemittanceReleaseError = null,
    commissionSplitError = null,
    statusUpdateError = null,
  } = opts

  const rpcMock = vi.fn(async (fn: string, args: Record<string, unknown>) => {
    capturedRpcCalls.push({ fn, args })

    if (fn === RPC.COMMISSION_SPLIT_REVERSE) {
      if (commissionSplitError) return { data: null, error: commissionSplitError }
      return { data: { id: 'reversal-s18-001' }, error: null }
    }

    if (fn === RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE) {
      if (taxLineReverseError) return { data: null, error: taxLineReverseError }
      return {
        data: {
          reversal_id: `tax-reversal-${(args?.p_parent_tax_line_split_id as string ?? '').slice(0, 8)}`,
          total_reversed_cents: args?.p_release_tax_cents ?? 0,
          created: true,
        },
        error: null,
      }
    }

    if (fn === RPC.TAX_REMITTANCE_RELEASE) {
      if (taxRemittanceReleaseError) return { data: null, error: taxRemittanceReleaseError }
      return {
        data: {
          ledger_id: `ledger-${(args?.p_jurisdiction as string ?? '').replace(/[^a-z0-9]/gi, '').toLowerCase().slice(0, 8)}`,
          new_collected_cents: 0,
          released_cents: args?.p_release_amount_cents ?? 0,
        },
        error: null,
      }
    }

    if (fn === RPC.RELEASE_DEPOSIT_FROM_SESSION) {
      return {
        data: { release_transaction_id: null, pool_available_cents: 0, total_released_cents: 0 },
        error: null,
      }
    }

    return { data: null, error: null }
  })

  const fromMock = vi.fn((table: string) => {
    if (table === 'stripe_charges') {
      const updateObj = {
        eq: vi.fn(() => Promise.resolve({ data: null, error: statusUpdateError })),
      }
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => ({
              single: vi.fn(async () => ({
                data: chargeRow,
                error: chargeRow === null ? { message: 'Not found' } : null,
              })),
            })),
          })),
        })),
        update: vi.fn(() => updateObj),
      }
    }

    if (table === 'commission_splits') {
      // Two query paths:
      // Path A: .eq(booking_id).eq('split').order.limit.maybeSingle → parent split
      // Path B: .eq(parent_split_id).eq('tax_line').select → tax_line children

      const maybeSingleParent = vi.fn(async () => ({
        data: parentSplitRow,
        error: null,
      }))

      const taxLinesMaybeSingle = vi.fn(async () => ({
        data: taxLineChildren,
        error: null,
      }))

      // Build a chainable mock that returns the right result depending on .eq() call sequence
      let eqCallCount = 0
      const innerEqChain = {
        order: vi.fn(() => ({
          limit: vi.fn(() => ({
            maybeSingle: maybeSingleParent,
          })),
        })),
        // For tax_line children query
        maybeSingle: taxLinesMaybeSingle,
        // Return data as array for select all
        then: undefined as undefined,
      }

      // Override: treat second .eq() differently based on the value
      const outerEq = vi.fn((_val: unknown) => {
        eqCallCount++
        return innerEqChain
      })

      return {
        select: vi.fn(() => ({
          eq: outerEq,
        })),
      }
    }

    if (table === 'project_deposit_transactions') {
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => ({
              order: vi.fn(() => ({
                limit: vi.fn(() => ({
                  maybeSingle: vi.fn(async () => ({ data: null, error: null })),
                })),
              })),
            })),
          })),
        })),
      }
    }

    return { select: vi.fn() }
  })

  return { rpc: rpcMock, from: fromMock } as unknown as SupabaseClient
}

// ---------------------------------------------------------------------------
// Helpers to introspect captured RPC calls
// ---------------------------------------------------------------------------

function getRpcCalls(fn: string) {
  return capturedRpcCalls.filter((c) => c.fn === fn)
}

// ---------------------------------------------------------------------------
// Base args factory
// ---------------------------------------------------------------------------

function makeRefundArgs(overrides: Partial<RefundChargeArgs> = {}): RefundChargeArgs {
  return {
    studioId: 'studio-s18-001',
    paymentIntentId: 'pi_test_s18_001',
    refundCents: cents(20000),
    reason: 'requested_by_customer',
    initiatedBy: 'user-owner-s18',
    ...overrides,
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('refundCharge — S18 tax reversal extension', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    capturedRpcCalls = []

    mockRefundsCreate.mockResolvedValue({
      id: 're_test_s18_001',
      status: 'succeeded',
      amount: 20000,
      transfer_reversal: 'trr_test_s18_001',
    })
  })

  it('happy full refund WITH tax_lines → calls TAX_LINE_REVERSE per child + TAX_REMITTANCE_RELEASE per jurisdiction', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')

    const sb = makeSupabaseMock({
      taxLineChildren: [
        {
          id: 'taxline-child-001',
          kind: 'tax_line',
          parent_split_id: 'split-s18-001',
          tax_amount_cents: 1800,
          jurisdiction: 'US-NY-NYC',
        },
      ],
    })

    const result = await refundCharge(sb, makeRefundArgs({ refundCents: cents(20000) }))

    expect(result.refundId).toBe('re_test_s18_001')

    // COMMISSION_SPLIT_TAX_LINE_REVERSE called once (one tax_line child)
    const taxReverseRpcs = getRpcCalls(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE)
    expect(taxReverseRpcs.length).toBe(1)
    expect(taxReverseRpcs[0]!.args['p_parent_tax_line_split_id']).toBe('taxline-child-001')

    // TAX_REMITTANCE_RELEASE called once (one jurisdiction)
    const taxReleaseRpcs = getRpcCalls(RPC.TAX_REMITTANCE_RELEASE)
    expect(taxReleaseRpcs.length).toBe(1)
    expect(taxReleaseRpcs[0]!.args['p_jurisdiction']).toBe('US-NY-NYC')
  })

  it('partial refund (50%) → release_tax_cents = Math.round(0.5 × tax_amount_cents)', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')

    mockRefundsCreate.mockResolvedValue({
      id: 're_test_s18_partial',
      status: 'succeeded',
      amount: 10000,
      transfer_reversal: 'trr_test_partial',
    })

    const sb = makeSupabaseMock({
      chargeRow: makeChargeRow({ amount_cents: 20000, tax_amount_cents: 1800 }),
      taxLineChildren: [
        {
          id: 'taxline-child-partial',
          kind: 'tax_line',
          parent_split_id: 'split-s18-partial',
          tax_amount_cents: 1800,
          jurisdiction: 'US-NY',
        },
      ],
    })

    await refundCharge(sb, makeRefundArgs({ refundCents: cents(10000) })) // 50%

    const taxReverseRpcs = getRpcCalls(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE)
    expect(taxReverseRpcs.length).toBe(1)

    // 50% of 1800 = 900
    const releaseTaxCents = taxReverseRpcs[0]!.args['p_release_tax_cents'] as number
    expect(releaseTaxCents).toBe(900)

    const taxReleaseRpcs = getRpcCalls(RPC.TAX_REMITTANCE_RELEASE)
    expect(taxReleaseRpcs.length).toBe(1)
    const releaseAmountCents = taxReleaseRpcs[0]!.args['p_release_amount_cents'] as number
    expect(releaseAmountCents).toBe(900)
  })

  it('no tax_line children → skips both COMMISSION_SPLIT_TAX_LINE_REVERSE and TAX_REMITTANCE_RELEASE', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')

    const sb = makeSupabaseMock({
      chargeRow: makeChargeRow({ tax_amount_cents: 0 }),
      taxLineChildren: [], // no children
    })

    await refundCharge(sb, makeRefundArgs())

    expect(getRpcCalls(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE).length).toBe(0)
    expect(getRpcCalls(RPC.TAX_REMITTANCE_RELEASE).length).toBe(0)
  })

  it('INVARIANT 5 still holds — reverse_transfer: true + refund_application_fee: true on Stripe call', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')
    const sb = makeSupabaseMock({})

    await refundCharge(sb, makeRefundArgs())

    expect(mockRefundsCreate).toHaveBeenCalledOnce()
    const [body] = mockRefundsCreate.mock.calls[0] as [Record<string, unknown>]
    expect(body['reverse_transfer']).toBe(true)
    expect(body['refund_application_fee']).toBe(true)
  })

  it('multiple jurisdictions (US-NY + US-NY-NYC) → 2 TAX_LINE_REVERSE + 2 TAX_REMITTANCE_RELEASE calls', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')

    const sb = makeSupabaseMock({
      taxLineChildren: [
        {
          id: 'taxline-ny',
          kind: 'tax_line',
          parent_split_id: 'split-multi-001',
          tax_amount_cents: 1200,
          jurisdiction: 'US-NY',
        },
        {
          id: 'taxline-nyc',
          kind: 'tax_line',
          parent_split_id: 'split-multi-001',
          tax_amount_cents: 600,
          jurisdiction: 'US-NY-NYC',
        },
      ],
      chargeRow: makeChargeRow({ tax_amount_cents: 1800 }),
    })

    await refundCharge(sb, makeRefundArgs({ refundCents: cents(20000) }))

    // Two tax_line reverse calls
    const taxReverseRpcs = getRpcCalls(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE)
    expect(taxReverseRpcs.length).toBe(2)

    const reversedParents = taxReverseRpcs.map((c) => c.args['p_parent_tax_line_split_id'])
    expect(reversedParents).toContain('taxline-ny')
    expect(reversedParents).toContain('taxline-nyc')

    // Two tax remittance release calls
    const taxReleaseRpcs = getRpcCalls(RPC.TAX_REMITTANCE_RELEASE)
    expect(taxReleaseRpcs.length).toBe(2)

    const releasedJurisdictions = taxReleaseRpcs.map((c) => c.args['p_jurisdiction'])
    expect(releasedJurisdictions).toContain('US-NY')
    expect(releasedJurisdictions).toContain('US-NY-NYC')
  })

  it('idempotency — same refund_id retried → both RPC idempotency keys are deterministic', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')

    const capturedIdemKeys: {
      taxReverse: string[]
      remittanceRelease: string[]
    } = { taxReverse: [], remittanceRelease: [] }

    // First call
    const sb1 = makeSupabaseMock({
      taxLineChildren: [
        {
          id: 'taxline-idem-001',
          kind: 'tax_line',
          parent_split_id: 'split-idem-001',
          tax_amount_cents: 500,
          jurisdiction: 'US-CA',
        },
      ],
    })

    await refundCharge(sb1, makeRefundArgs())

    getRpcCalls(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE).forEach((c) => {
      capturedIdemKeys.taxReverse.push(c.args['p_idempotency_key'] as string)
    })
    getRpcCalls(RPC.TAX_REMITTANCE_RELEASE).forEach((c) => {
      capturedIdemKeys.remittanceRelease.push(c.args['p_idempotency_key'] as string)
    })

    // Reset and retry with the same args
    capturedRpcCalls = []
    vi.clearAllMocks()
    mockRefundsCreate.mockResolvedValue({
      id: 're_test_s18_001',
      status: 'succeeded',
      amount: 20000,
      transfer_reversal: 'trr_test_s18_001',
    })

    const sb2 = makeSupabaseMock({
      taxLineChildren: [
        {
          id: 'taxline-idem-001',
          kind: 'tax_line',
          parent_split_id: 'split-idem-001',
          tax_amount_cents: 500,
          jurisdiction: 'US-CA',
        },
      ],
    })

    await refundCharge(sb2, makeRefundArgs())

    const secondTaxReverseKeys = getRpcCalls(RPC.COMMISSION_SPLIT_TAX_LINE_REVERSE).map(
      (c) => c.args['p_idempotency_key'] as string,
    )
    const secondRemittanceKeys = getRpcCalls(RPC.TAX_REMITTANCE_RELEASE).map(
      (c) => c.args['p_idempotency_key'] as string,
    )

    // Keys must be identical across retries
    expect(capturedIdemKeys.taxReverse[0]).toBe(secondTaxReverseKeys[0])
    expect(capturedIdemKeys.remittanceRelease[0]).toBe(secondRemittanceKeys[0])

    // Keys must start with inkos_ prefix (INVARIANT 2 convention)
    expect(capturedIdemKeys.taxReverse[0]).toMatch(/^inkos_/)
    expect(capturedIdemKeys.remittanceRelease[0]).toMatch(/^inkos_/)
  })

  it('tax_line RPC failure → log error + continue (refund still completes, Leg 4 reconciliation recovers)', async () => {
    const { refundCharge } = await import('@/lib/stripe/refunds')

    const sb = makeSupabaseMock({
      taxLineReverseError: { message: 'DB constraint violation on tax_line_reverse' },
      taxLineChildren: [
        {
          id: 'taxline-fail-001',
          kind: 'tax_line',
          parent_split_id: 'split-fail-001',
          tax_amount_cents: 750,
          jurisdiction: 'US-TX',
        },
      ],
    })

    // Must NOT throw — tax_line failure is non-fatal after Stripe refund succeeded
    const result = await refundCharge(sb, makeRefundArgs())

    expect(result.refundId).toBe('re_test_s18_001')

    // Error must be logged so Leg 4 reconciliation can detect and repair
    expect(mockLoggerError).toHaveBeenCalledWith(
      expect.objectContaining({ refund_id: 're_test_s18_001' }),
      expect.stringContaining('CRITICAL'),
    )
  })
})

/**
 * Integration tests: lib/stripe/charges — S18 tip routing modes
 *
 * Stripe SDK mocked. Supabase client mocked.
 * All tests run unconditionally (no DB required).
