// ---------------------------------------------------------------------------
// Supabase mock factory (country-aligned, no deposit drawdown)
// ---------------------------------------------------------------------------

function makeSupabaseMock(): SupabaseClient {
  const makeSingle = <T>(data: T) => ({
    single: vi.fn(async () => ({ data, error: null })),
  })

  const rpcMock = vi.fn(async (fn: string) => {
    if (fn === RPC.STRIPE_CHARGE_RECORD) {
      return { data: { id: 'charge-row-tip-001', created: true }, error: null }
    }
    return { data: null, error: null }
  })

  const fromMock = vi.fn((table: string) => {
    if (table === 'studios') {
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => makeSingle({ country: 'US' })),
        })),
      }
    }
    if (table === 'stripe_connected_accounts') {
      return {
        select: vi.fn(() => ({
          eq: vi.fn(() => ({
            eq: vi.fn(() => makeSingle({ country: 'US' })),
          })),
        })),
      }
    }
    return {
      select: vi.fn(() => ({
        eq: vi.fn(() => ({
          eq: vi.fn(() => ({
            single: vi.fn(async () => ({ data: null, error: null })),
          })),
          single: vi.fn(async () => ({ data: null, error: null })),
        })),
      })),
    }
  })

  return { rpc: rpcMock, from: fromMock } as unknown as SupabaseClient
}

