    currency: 'usd',
    baseAmountCents: cents(10000),   // $100
    tipAmountCents: cents(1500),     // $15
    depositDrawdownCents: cents(0),
    commissionPct: 70,               // artist 70%, studio 30% → applicationFeeCents = 3000
    artistConnectedAccountId: 'acct_artist_tiproute_456',
