}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('createSessionPaymentIntent — S18 tip routing modes', () => {
  let capturedPiBody: Record<string, unknown> | undefined

  beforeEach(() => {
    vi.clearAllMocks()
    capturedPiBody = undefined

    mockPaymentIntentsCreate.mockImplementation(
      async (body: Record<string, unknown>) => {
        capturedPiBody = body
        return {
          id: 'pi_tiproute_001',
          client_secret: 'pi_tiproute_001_secret',
          status: 'succeeded',
          amount: (body['amount'] as number) ?? 11500,
          currency: 'usd',
          metadata: body['metadata'],
        }
      },
    )
  })

  it('tipPoolEnabled: false — tip flows to artist; application_fee = commissionPct share only (no tip included)', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
    const sb = makeSupabaseMock()

    await createSessionPaymentIntent(sb, makeArgs({ tipPoolEnabled: false }))

    expect(capturedPiBody).toBeDefined()
    // baseAmountCents = 10000, commissionPct = 70 → artist gets 70%, studio gets 30%
    // applicationFeeCents = round(10000 * 0.30) = 3000
    // tipPoolEnabled: false → tip flows to artist's destination, NOT added to application_fee
    expect(capturedPiBody!['application_fee_amount']).toBe(3000)
    // Destination should be artist's connected account
    expect((capturedPiBody!['transfer_data'] as Record<string, unknown>)?.['destination']).toBe(
      'acct_artist_tiproute_456',
    )
  })

  it('tipPoolEnabled: true — tip flows to studio; application_fee = commissionPct share + tipAmountCents', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
    const sb = makeSupabaseMock()

    await createSessionPaymentIntent(sb, makeArgs({ tipPoolEnabled: true }))

    expect(capturedPiBody).toBeDefined()
    // applicationFeeCents = 3000 (30% of base) + 1500 (tip) = 4500
    expect(capturedPiBody!['application_fee_amount']).toBe(4500)
  })

  it('no artist Connect account → application_fee = baseAmountCents + tipAmountCents regardless of pool flag', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')
    const sb = makeSupabaseMock()

    // Test with tipPoolEnabled: false (should not matter — no artist account)
    await createSessionPaymentIntent(
      sb,
      makeArgs({
        artistConnectedAccountId: null,
        tipPoolEnabled: false,
      }),
    )

    expect(capturedPiBody).toBeDefined()
    // No artist account → studio keeps everything: base + tip = 10000 + 1500 = 11500
    expect(capturedPiBody!['application_fee_amount']).toBe(11500)

    // Verify same result when tipPoolEnabled: true (should still be 11500)
    vi.clearAllMocks()
    capturedPiBody = undefined
    mockPaymentIntentsCreate.mockImplementation(async (body: Record<string, unknown>) => {
      capturedPiBody = body
      return { id: 'pi_tiproute_002', client_secret: null, status: 'succeeded', amount: 11500, currency: 'usd', metadata: body['metadata'] }
    })

    const sb2 = makeSupabaseMock()
    await createSessionPaymentIntent(
      sb2,
      makeArgs({
        artistConnectedAccountId: null,
        tipPoolEnabled: true,
      }),
    )

    expect(capturedPiBody!['application_fee_amount']).toBe(11500)
  })

  it('PI metadata includes inkos_tip_destination matching the tip routing mode', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')

    // Case 1: tipPoolEnabled false → inkos_tip_destination = 'artist'
    const sb1 = makeSupabaseMock()
    await createSessionPaymentIntent(sb1, makeArgs({ tipPoolEnabled: false }))

    const metadata1 = capturedPiBody!['metadata'] as Record<string, string>
    expect(metadata1['inkos_tip_destination']).toBe('artist')
    expect(metadata1['inkos_tip_pool_enabled']).toBe('false')

    // Case 2: tipPoolEnabled true → inkos_tip_destination = 'studio'
    vi.clearAllMocks()
    capturedPiBody = undefined
    mockPaymentIntentsCreate.mockImplementation(async (body: Record<string, unknown>) => {
      capturedPiBody = body
      return { id: 'pi_tiproute_003', client_secret: null, status: 'succeeded', amount: 11500, currency: 'usd', metadata: body['metadata'] }
    })

    const sb2 = makeSupabaseMock()
    await createSessionPaymentIntent(sb2, makeArgs({ tipPoolEnabled: true }))

    const metadata2 = capturedPiBody!['metadata'] as Record<string, string>
    expect(metadata2['inkos_tip_destination']).toBe('studio')
    expect(metadata2['inkos_tip_pool_enabled']).toBe('true')
  })

  it('INVARIANT 4 — application_fee_amount is defined and positive in all tip routing configurations', async () => {
    const { createSessionPaymentIntent } = await import('@/lib/stripe/charges')

    const configurations: Array<Partial<CreateSessionPaymentIntentArgs>> = [
      { tipPoolEnabled: false, artistConnectedAccountId: 'acct_artist_tiproute_456' },
      { tipPoolEnabled: true,  artistConnectedAccountId: 'acct_artist_tiproute_456' },
      { tipPoolEnabled: false, artistConnectedAccountId: null },
      { tipPoolEnabled: true,  artistConnectedAccountId: null },
    ]

    for (const config of configurations) {
      vi.clearAllMocks()
      capturedPiBody = undefined
      mockPaymentIntentsCreate.mockImplementation(async (body: Record<string, unknown>) => {
        capturedPiBody = body
        return { id: 'pi_inv4_check', client_secret: null, status: 'succeeded', amount: 11500, currency: 'usd', metadata: body['metadata'] }
      })

      const sb = makeSupabaseMock()
      await createSessionPaymentIntent(sb, makeArgs(config))

      // INVARIANT 4: application_fee_amount must be defined + positive integer
      expect(capturedPiBody!['application_fee_amount']).toBeDefined()
      expect(typeof capturedPiBody!['application_fee_amount']).toBe('number')
      expect(capturedPiBody!['application_fee_amount'] as number).toBeGreaterThan(0)
    }
  })
})
